"""
permission_service - Prueft Benutzerberechtigungen fuer Tools anhand von
Windows-Benutzernamen und Datenbankeintraegen.

Verwendung:
    from core_services.auth import check_user_permission
    check_user_permission: Prueft, ob der aktuelle Windows-Benutzer die
    Berechtigung fuer ein tool hat.
"""

import logging
import os
from typing import TYPE_CHECKING

import mariadb

if TYPE_CHECKING:
    from ..db.client import DbCredentials

logger = logging.getLogger(__name__)


def check_user_permission(
    tool: str, database: str = "dbm_lesermarkt", db_credentials: "DbCredentials | None" = None
) -> bool:
    """Prueft, ob der aktuelle Windows-Benutzer die Berechtigung fuer ein tool hat.

    Args:
        tool: Der Name des Tools, fuer das die Berechtigung geprueft wird.
        database: Der Name der Datenbank, in der die Berechtigungen liegen.
        db_credentials: Optionale direkte DB-Zugangsdaten als DbCredentials.
            Die erwarteten Felder sind zentral in DbCredentials dokumentiert.

    Returns:
        True wenn der Benutzer berechtigt ist, sonst False.

    Raises:
        OSError: Wenn der Windows-Anmeldename nicht ermittelt werden kann.
        mariadb.Error: Wenn die Berechtigungsabfrage fehlschlaegt.
    """

    from ..db.client import connect_to_db

    windows_user = os.getlogin()
    connection = None
    try:
        connection = connect_to_db(database, credentials=db_credentials)

        cursor = connection.cursor(dictionary=True)

        sql_query = """
            SELECT
                case when be_tools.tool = %s then 1 ELSE 0 END AS berechtigung
            FROM
                tb_berechtigung_user be_user
            LEFT JOIN
                tb_berechtigung_tools be_tools on be_user.berechtigung = be_tools.berechtigung
            WHERE
                be_user.userid = %s AND be_tools.tool = %s
        """

        parameters = (tool, windows_user, tool)

        cursor.execute(sql_query, parameters)

        result = cursor.fetchone()

        if result:
            if result["berechtigung"] == 1:
                return True
            else:
                return False
        else:
            logger.warning("Keine Berechtigungseintraege fuer Benutzer %s und tool %s", windows_user, tool)
            return False

    except mariadb.Error as e:
        logger.error("Fehler beim Abrufen der Berechtigung: %s", e, exc_info=True)
        raise

    finally:
        if connection:
            connection.close()
